import functools

def count_calls(func):
    @functools.wraps(func)  # keep name and docstring
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)  # return the result
    wrapper.calls = 0
    return wrapper

@count_calls  # greet = count_calls(greet)
def greet(name):
    return f"Hello, {name}"

greet("Ada")
print(greet.calls, greet.__name__)  # 1 greet

def retry(times):  # a factory: returns a decorator
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times - 1):
                try:
                    return func(*args, **kwargs)
                except ConnectionError:
                    pass
            return func(*args, **kwargs)  # last try
        return wrapper
    return decorator

