from contextlib import contextmanager

accounts = {"ana": 100, "bo": 50}

@contextmanager
def transaction(data):
    # Take a snapshot, yield data, and restore the snapshot if the block raises.
    # Re-raise the error after restoring so the caller still sees it.
    yield data

def transfer(data, src, dst, amount):
    data[src] -= amount
    if data[src] < 0:
        raise ValueError(f"{src} would go negative")
    data[dst] += amount

with transaction(accounts) as data:
    transfer(data, "ana", "bo", 30)
print(accounts)

try:
    with transaction(accounts) as data:
        transfer(data, "bo", "ana", 500)
except ValueError as err:
    print("rolled back:", err)
print(accounts)

