def paths(r, c):
    """Right/down paths from (0, 0) to (r, c) on a grid."""
    global calls
    calls += 1
    if r == 0 or c == 0:
        return 1
    return paths(r - 1, c) + paths(r, c - 1)

print(paths(10, 10))
