import json

class AppError(Exception):
    """Base: callers can catch everything we raise."""

class ConfigError(AppError):
    pass

def load_port(text):
    try:
        return json.loads(text)["port"]
    except json.JSONDecodeError as err:
        raise ConfigError("config is not valid JSON") from err
    except KeyError:
        raise ConfigError("config is missing 'port'") from None

