class OrderError(Exception):
    pass

PRICES = {"pen": 150, "pad": 300}

def parse_order(line):
    """'item,qty' -> total price in cents."""
    item, qty = line.split(",")
    return PRICES[item] * int(qty)

for line in ["pen,2", "pad,x", "ink,1"]:
    try:
        print(line, "->", parse_order(line))
    except OrderError as err:
        print(line, "->", err, f"(caused by {type(err.__cause__).__name__})")

import timeit
from collections import deque

n = 10_000

def drain_list():
    q = list(range(n))
    while q:
        q.pop(0)

def drain_deque():
    q = deque(range(n))
    while q:
        q.popleft()

print(f"list:  {timeit.timeit(drain_list, number=3):.3f} s")
print(f"deque: {timeit.timeit(drain_deque, number=3):.3f} s")

